import Foundation
import SpriteKit
import UIKit

// THE LAST HUNTER — animated Cursed Forest environment.
// Add this file to Sources/V3/.
// All artwork is embedded in Base64, so build-ipa.yml does NOT need PNG copy steps.

@MainActor
enum CursedForestEnvironment {

    private static let rootName = "__the_last_hunter_cursed_forest_v1"

    // MARK: - Public

    static func install(
        on scene: SKScene
    ) {
        scene.childNode(
            withName: rootName
        )?.removeFromParent()

        hideLegacyProceduralForest(
            in: scene
        )

        let root = SKNode()
        root.name = rootName
        root.zPosition = 0
        scene.addChild(root)

        let sceneSize = scene.size

        addBackdrop(
            to: root,
            sceneSize: sceneSize
        )

        addMoonGlow(
            to: root,
            sceneSize: sceneSize
        )

        addFog(
            to: root,
            sceneSize: sceneSize
        )

        addDust(
            to: root,
            sceneSize: sceneSize
        )

        addLeaves(
            to: root,
            sceneSize: sceneSize
        )
    }

    // MARK: - Hide old procedural forest

    private static func hideLegacyProceduralForest(
        in scene: SKScene
    ) {
        let expectedLayerZ: Set<Int> = [
            -100, -80, -60, -30,
            10, 40, 70
        ]

        guard let world =
            scene.children.first(
                where: { node in
                    let values =
                        Set(
                            node.children.map {
                                Int(
                                    $0.zPosition
                                )
                            }
                        )

                    return expectedLayerZ
                        .isSubset(
                            of: values
                        )
                }
            )
        else {
            return
        }

        let environmentZ: Set<Int> = [
            -100, -80, -60, -30, 70
        ]

        for layer in world.children {
            if environmentZ.contains(
                Int(
                    layer.zPosition
                )
            ) {
                layer.isHidden = true
            }
        }
    }

    // MARK: - Backdrop

    private static func addBackdrop(
        to root: SKNode,
        sceneSize: CGSize
    ) {
        let sprite =
            SKSpriteNode(
                texture:
                    Assets.background
            )

        sprite.name = "cursedForestBackdrop"
        sprite.anchorPoint =
            CGPoint(
                x: 0.5,
                y: 0.5
            )

        sprite.position =
            CGPoint(
                x:
                    sceneSize.width
                    * 0.5,
                y:
                    sceneSize.height
                    * 0.5
            )

        let source =
            Assets.background.size()

        let scale =
            max(
                sceneSize.width
                / max(
                    source.width,
                    1
                ),
                sceneSize.height
                / max(
                    source.height,
                    1
                )
            )

        sprite.setScale(
            scale
        )

        sprite.zPosition = -20
        root.addChild(
            sprite
        )
    }

    // MARK: - Moon

    private static func addMoonGlow(
        to root: SKNode,
        sceneSize: CGSize
    ) {
        let glow =
            SKSpriteNode(
                texture:
                    Assets.moonGlow
            )

        glow.name = "moonGlow"
        glow.position =
            CGPoint(
                x:
                    sceneSize.width
                    * 0.53,
                y:
                    sceneSize.height
                    * 0.86
            )

        let side =
            sceneSize.width
            * 0.50

        glow.size =
            CGSize(
                width: side,
                height: side
            )

        glow.alpha = 0.13
        glow.blendMode = .add
        glow.zPosition = -14

        root.addChild(
            glow
        )

        let breatheOut =
            SKAction.group(
                [
                    .scale(
                        to: 1.055,
                        duration: 2.8
                    ),
                    .fadeAlpha(
                        to: 0.21,
                        duration: 2.8
                    )
                ]
            )

        breatheOut.timingMode =
            .easeInEaseOut

        let breatheIn =
            SKAction.group(
                [
                    .scale(
                        to: 0.97,
                        duration: 3.2
                    ),
                    .fadeAlpha(
                        to: 0.12,
                        duration: 3.2
                    )
                ]
            )

        breatheIn.timingMode =
            .easeInEaseOut

        glow.run(
            .repeatForever(
                .sequence(
                    [
                        breatheOut,
                        breatheIn
                    ]
                )
            ),
            withKey:
                "moonBreathing"
        )
    }

    // MARK: - Fog

    private static func addFog(
        to root: SKNode,
        sceneSize: CGSize
    ) {
        let back =
            SKSpriteNode(
                texture:
                    Assets.fogBack
            )

        back.name = "fogBack"
        back.position =
            CGPoint(
                x:
                    sceneSize.width
                    * 0.48,
                y:
                    sceneSize.height
                    * 0.30
            )

        back.size =
            CGSize(
                width:
                    sceneSize.width
                    * 1.38,
                height:
                    sceneSize.height
                    * 0.18
            )

        back.alpha = 0.13
        back.zPosition = 2
        root.addChild(
            back
        )

        let backMove =
            SKAction.moveBy(
                x:
                    sceneSize.width
                    * 0.16,
                y: 0,
                duration: 13.0
            )

        backMove.timingMode =
            .easeInEaseOut

        back.run(
            .repeatForever(
                .sequence(
                    [
                        backMove,
                        backMove.reversed()
                    ]
                )
            ),
            withKey:
                "fogBackDrift"
        )

        let front =
            SKSpriteNode(
                texture:
                    Assets.fogFront
            )

        front.name = "fogFront"
        front.position =
            CGPoint(
                x:
                    sceneSize.width
                    * 0.52,
                y:
                    sceneSize.height
                    * 0.18
            )

        front.size =
            CGSize(
                width:
                    sceneSize.width
                    * 1.48,
                height:
                    sceneSize.height
                    * 0.20
            )

        front.alpha = 0.17
        front.zPosition = 22
        root.addChild(
            front
        )

        let frontMove =
            SKAction.moveBy(
                x:
                    -sceneSize.width
                    * 0.19,
                y: 0,
                duration: 9.5
            )

        frontMove.timingMode =
            .easeInEaseOut

        let fogPulseOut =
            SKAction.fadeAlpha(
                to: 0.22,
                duration: 4.2
            )

        let fogPulseIn =
            SKAction.fadeAlpha(
                to: 0.14,
                duration: 4.8
            )

        front.run(
            .repeatForever(
                .sequence(
                    [
                        frontMove,
                        frontMove.reversed()
                    ]
                )
            ),
            withKey:
                "fogFrontDrift"
        )

        front.run(
            .repeatForever(
                .sequence(
                    [
                        fogPulseOut,
                        fogPulseIn
                    ]
                )
            ),
            withKey:
                "fogFrontPulse"
        )
    }

    // MARK: - Leaves

    private static func addLeaves(
        to root: SKNode,
        sceneSize: CGSize
    ) {
        let textures =
            Assets.leafTextures

        guard !textures.isEmpty else {
            return
        }

        for index in 0..<14 {
            let texture =
                textures[
                    index
                    % textures.count
                ]

            let leaf =
                SKSpriteNode(
                    texture: texture
                )

            leaf.name =
                "forestLeaf_\(index)"

            leaf.zPosition =
                index.isMultiple(
                    of: 3
                )
                ? 6
                : 26

            root.addChild(
                leaf
            )

            resetLeaf(
                leaf,
                sceneSize:
                    sceneSize,
                firstPass: true
            )

            animateLeaf(
                leaf,
                sceneSize:
                    sceneSize
            )
        }
    }

    private static func resetLeaf(
        _ leaf: SKSpriteNode,
        sceneSize: CGSize,
        firstPass: Bool
    ) {
        let side =
            CGFloat.random(
                in:
                    firstPass
                    ? 9...19
                    : 10...20
            )

        let aspect =
            max(
                leaf.texture?.size()
                    .height
                ?? side,
                1
            )
            /
            max(
                leaf.texture?.size()
                    .width
                ?? side,
                1
            )

        leaf.size =
            CGSize(
                width: side,
                height:
                    side
                    * min(
                        max(
                            aspect,
                            0.65
                        ),
                        1.55
                    )
            )

        leaf.position =
            CGPoint(
                x:
                    CGFloat.random(
                        in:
                            -18
                            ...(
                                sceneSize.width
                                + 18
                            )
                    ),
                y:
                    firstPass
                    ? CGFloat.random(
                        in:
                            sceneSize.height
                            * 0.34
                            ...
                            sceneSize.height
                            * 1.02
                    )
                    : sceneSize.height
                        + CGFloat.random(
                            in: 8...90
                        )
            )

        leaf.alpha =
            CGFloat.random(
                in: 0.24...0.58
            )

        leaf.zRotation =
            CGFloat.random(
                in:
                    -CGFloat.pi
                    ...
                    CGFloat.pi
            )
    }

    private static func animateLeaf(
        _ leaf: SKSpriteNode,
        sceneSize: CGSize
    ) {
        let duration =
            TimeInterval.random(
                in: 6.2...11.8
            )

        let xDrift =
            CGFloat.random(
                in: -85...85
            )

        let yDrop =
            CGFloat.random(
                in: 120...260
            )

        let move =
            SKAction.moveBy(
                x: xDrift,
                y: -yDrop,
                duration: duration
            )

        move.timingMode =
            .easeInEaseOut

        let rotate =
            SKAction.rotate(
                byAngle:
                    CGFloat.random(
                        in:
                            -CGFloat.pi
                            * 2.0
                            ...
                            CGFloat.pi
                            * 2.0
                    ),
                duration: duration
            )

        let swayRight =
            SKAction.moveBy(
                x:
                    CGFloat.random(
                        in: 7...18
                    ),
                y: 0,
                duration:
                    duration
                    * 0.23
            )

        let swayLeft =
            swayRight.reversed()

        let sway =
            SKAction.repeat(
                .sequence(
                    [
                        swayRight,
                        swayLeft
                    ]
                ),
                count: 2
            )

        leaf.run(
            .sequence(
                [
                    .group(
                        [
                            move,
                            rotate,
                            sway
                        ]
                    ),
                    .run {
                        [weak leaf] in

                        guard let leaf else {
                            return
                        }

                        resetLeaf(
                            leaf,
                            sceneSize:
                                sceneSize,
                            firstPass:
                                false
                        )

                        animateLeaf(
                            leaf,
                            sceneSize:
                                sceneSize
                        )
                    }
                ]
            ),
            withKey:
                "leafLoop"
        )
    }

    // MARK: - Dust

    private static func addDust(
        to root: SKNode,
        sceneSize: CGSize
    ) {
        let textures =
            Assets.dustTextures

        guard !textures.isEmpty else {
            return
        }

        for index in 0..<10 {
            let mote =
                SKSpriteNode(
                    texture:
                        textures[
                            index
                            % textures.count
                        ]
                )

            mote.name =
                "forestDust_\(index)"

            let side =
                CGFloat.random(
                    in: 5...11
                )

            mote.size =
                CGSize(
                    width: side,
                    height: side
                )

            mote.position =
                CGPoint(
                    x:
                        CGFloat.random(
                            in:
                                0
                                ...
                                sceneSize.width
                        ),
                    y:
                        CGFloat.random(
                            in:
                                sceneSize.height
                                * 0.28
                                ...
                                sceneSize.height
                                * 0.72
                        )
                )

            mote.alpha =
                CGFloat.random(
                    in: 0.07...0.19
                )

            mote.blendMode = .add
            mote.zPosition = 5

            root.addChild(
                mote
            )

            animateDust(
                mote
            )
        }
    }

    private static func animateDust(
        _ mote: SKSpriteNode
    ) {
        let duration =
            TimeInterval.random(
                in: 4.5...8.0
            )

        let drift =
            SKAction.moveBy(
                x:
                    CGFloat.random(
                        in: -18...18
                    ),
                y:
                    CGFloat.random(
                        in: 16...48
                    ),
                duration: duration
            )

        drift.timingMode =
            .easeInEaseOut

        let brighten =
            SKAction.fadeAlpha(
                to:
                    CGFloat.random(
                        in: 0.16...0.27
                    ),
                duration:
                    duration
                    * 0.45
            )

        let dim =
            SKAction.fadeAlpha(
                to:
                    CGFloat.random(
                        in: 0.05...0.12
                    ),
                duration:
                    duration
                    * 0.55
            )

        mote.run(
            .repeatForever(
                .group(
                    [
                        .sequence(
                            [
                                drift,
                                drift.reversed()
                            ]
                        ),
                        .repeatForever(
                            .sequence(
                                [
                                    brighten,
                                    dim
                                ]
                            )
                        )
                    ]
                )
            ),
            withKey:
                "dustLoop"
        )
    }

    // MARK: - Embedded assets

    private enum Assets {

        static let background =
            texture(
                base64:
                    backgroundBase64,
                filtering:
                    .nearest
            )

        static let leavesSheet =
            texture(
                base64:
                    leavesBase64,
                filtering:
                    .nearest
            )

        static let fogBack =
            texture(
                base64:
                    fogBackBase64,
                filtering:
                    .linear
            )

        static let fogFront =
            texture(
                base64:
                    fogFrontBase64,
                filtering:
                    .linear
            )

        static let moonGlow =
            texture(
                base64:
                    moonGlowBase64,
                filtering:
                    .linear
            )

        static let dustSheet =
            texture(
                base64:
                    dustBase64,
                filtering:
                    .nearest
            )

        static let leafTextures:
            [SKTexture] =
                gridTextures(
                    sheet:
                        leavesSheet,
                    columns: 3,
                    rows: 2
                )

        static let dustTextures:
            [SKTexture] =
                gridTextures(
                    sheet:
                        dustSheet,
                    columns: 4,
                    rows: 3
                )

        private static func texture(
            base64: String,
            filtering:
                SKTextureFilteringMode
        ) -> SKTexture {
            guard
                let data =
                    Data(
                        base64Encoded:
                            base64,
                        options:
                            .ignoreUnknownCharacters
                    ),
                let image =
                    UIImage(
                        data: data
                    )
            else {
                return SKTexture(
                    image:
                        UIImage()
                )
            }

            let texture =
                SKTexture(
                    image: image
                )

            texture.filteringMode =
                filtering

            return texture
        }

        private static func gridTextures(
            sheet: SKTexture,
            columns: Int,
            rows: Int
        ) -> [SKTexture] {
            guard
                columns > 0,
                rows > 0
            else {
                return []
            }

            var result:
                [SKTexture] = []

            for row in 0..<rows {
                for column in 0..<columns {
                    let rect =
                        CGRect(
                            x:
                                CGFloat(column)
                                / CGFloat(columns),
                            y:
                                CGFloat(
                                    rows
                                    - row
                                    - 1
                                )
                                / CGFloat(rows),
                            width:
                                1
                                / CGFloat(columns),
                            height:
                                1
                                / CGFloat(rows)
                        )

                    let texture =
                        SKTexture(
                            rect: rect,
                            in: sheet
                        )

                    texture.filteringMode =
                        .nearest

                    result.append(
                        texture
                    )
                }
            }

            return result
        }

